"""Build factual public pages from the deployed API contracts. No credentials."""
from pathlib import Path
import html
import json

HERE = Path(__file__).resolve().parent
BASE = 'https://commerce-quality-api.onrender.com'
RAPID = 'https://rapidapi.com/tuyentn23/api/'
STYLE = '''body{margin:0;background:#f6f8fc;color:#18253c;font:17px/1.7 system-ui,sans-serif}main{max-width:920px;margin:auto;padding:36px 22px}nav a{margin-right:18px}a{color:#1454ba}h1{font-size:clamp(30px,5vw,44px);line-height:1.2}h2{margin-top:36px}pre{background:#14233d;color:#edf4ff;padding:20px;overflow:auto;border-radius:12px;font-size:14px}section{background:white;border:1px solid #dfe5ef;border-radius:16px;padding:24px;margin:20px 0}.cta{display:inline-block;background:#175cd3;color:white;padding:12px 20px;border-radius:8px;text-decoration:none;font-weight:650}footer{border-top:1px solid #ccd6e4;margin-top:40px;padding-top:20px;font-size:14px}.note{color:#47566d}li{margin:8px 0}code{overflow-wrap:anywhere}table{border-collapse:collapse;width:100%}td,th{padding:10px;text-align:left;border-bottom:1px solid #ddd}'''
PAGES = [
    ('invoice-arithmetic-validator', 'Invoice arithmetic validation API',
     'Check invoice totals, subtotals and line items after OCR. Decimal arithmetic, mismatch details and a free RapidAPI trial.',
     '/v1/invoices/validate',
     {'subtotal':'100','tax':'10','shipping':'0','discount':'0','total':'120','lines':[{'quantity':'2','unit_price':'50','line_total':'100'}]},
     {'valid':False,'expected_total':'110','issues':[{'field':'total','expected':'110','actual':'120','difference':'10'}],'scope':'arithmetic_only'},
     '''<p>Use this API after invoice extraction and before a reviewed accounting import. It checks <code>total = subtotal + tax + shipping - discount</code>, supplied line totals against subtotal, and each line's quantity × unit price.</p><p>For example, subtotal 100 plus tax 10 should produce total 110. A supplied total of 120 returns a mismatch with the expected amount and difference.</p><h2>Amounts, rounding and missing values</h2><p>Send decimal strings. Default tolerance is 0.01 in the units you supply; choose a tolerance for your workflow. Up to 200 lines and 1 MB per request. Do not turn missing extraction fields into zero: review them first.</p><p>Arithmetic consistency does not establish invoice authenticity, tax compliance, vendor identity, fraud detection or currency conversion. Consistently wrong inputs can pass.</p><h2>Connect extraction to validation</h2><p>Map the extractor's <code>invoice.tax_amount</code> to validator <code>tax</code>, and each <code>line_items[].amount</code> to <code>lines[].line_total</code>. Require subtotal and total before calling the validator. See the <a href="https://github.com/tuyentn23-dot/commerce-quality-api/blob/main/examples/README.md">Python pipeline and n8n mapping guide</a>. The n8n template has not been tested in a live n8n installation.</p>'''),
    ('vn-contact-cleaner', 'Vietnam phone and email normalization API',
     'Normalize Vietnamese mobile numbers to +84 and check conservative email syntax in batches of up to 200 contacts. Try VN Contact Cleaner on RapidAPI.',
     '/v1/contacts/normalize',
     {'contacts':[{'email':'User@EXAMPLE.COM ','phone':'+84 912 345 678'},{'email':'bad-email','phone':'abc'},{}]},
     {'count':3,'results':[{'email':'User@example.com','email_syntax_valid':True,'phone_e164':'+84912345678','vn_mobile_shape_valid':True,'scope':'syntax_only','deliverability_verified':False,'ownership_verified':False},{'email':None,'email_syntax_valid':False,'phone_e164':None,'vn_mobile_shape_valid':False,'scope':'syntax_only','deliverability_verified':False,'ownership_verified':False},{'email':None,'email_syntax_valid':None,'phone_e164':None,'vn_mobile_shape_valid':None,'scope':'syntax_only','deliverability_verified':False,'ownership_verified':False}]},
     '''<p>Prepare contact data before a Vietnam CRM or order import. Submit 1–200 contacts in one HTTP request, up to 1 MB. Results preserve input order: <code>results[i]</code> describes <code>contacts[i]</code>.</p><h2>How Vietnamese mobile numbers are normalized</h2><p>Accepted number shapes start with 0, +84, 0084 or bare 84. Spaces, parentheses, dots and hyphens are removed. A supported ten-digit local mobile shape such as <code>0912345678</code> becomes <code>+84912345678</code>. Landlines, extensions and old eleven-digit local numbers are unsupported.</p><h2>Email case and invalid fields</h2><p>The email domain is lowercased and IDN-encoded; local-part case is preserved. Outer whitespace is trimmed. Invalid supplied values return false validity and null normalized values; omitted values return null validity. This conservative ASCII local-part syntax check does not support every RFC email address.</p><p>A valid shape does not mean a number is allocated or reachable. This API does not verify mailboxes, deliverability, consent or ownership. Use a verification provider if you need live checks.</p><h2>Chuẩn hóa số điện thoại Việt Nam</h2><p>Dùng trước khi nhập danh sách vào CRM: chuyển số di động đúng định dạng sang +84 và báo trường thiếu hoặc sai cú pháp. Kết quả không xác nhận thuê bao đang hoạt động hay email tồn tại.</p>'''),
    ('batch-duplicate-candidates', 'Exact duplicate detection API for JSON batches',
     'Find exact duplicate candidates by selected scalar keys in up to 500 JSON records. Returns review groups and skipped indices, with no deletion or merging.',
     '/v1/records/duplicate-candidates',
     {'records':[{'order_id':' A-001 '},{'order_id':'A-001'},{'order_id':''},{'order_id':'B-002'}],'key_fields':['order_id'],'casefold':False},
     {'candidate_groups':[[0,1]],'candidate_record_count':2,'skipped_indices':[2],'scope':'exact_selected_keys','records_deleted':0},
     '''<p>Find exact duplicate candidates before a CRM, order or ETL import. Send 1–500 JSON records and choose 1–8 top-level scalar fields. The maximum request payload is 1 MB. Review the returned candidates before importing; the API never deletes or merges records.</p><h2>Single keys and compound keys</h2><p>Multiple selected fields use AND matching: all values must match. Strings are trimmed. Enable <code>casefold: true</code> to compare strings without case, including Unicode case folding. Types remain distinct: <code>true</code>, <code>1</code>, <code>1.0</code> and <code>"1"</code> do not collide.</p><h2>Incomplete keys are skipped</h2><p>Missing, null, blank, object and array key values skip the record. Groups and skipped indices are zero-based. Nested field paths and fuzzy names are unsupported. This checks only the submitted batch, not records already in a CRM.</p><h2>Normalize before comparing contacts</h2><p>If phone or email formatting differs, first use <a href="/vn-contact-cleaner">VN Contact Cleaner</a>, then compare selected normalized values. Shared household numbers and role mailboxes may describe different people: matching keys are candidates, not proof of identical identity.</p>'''),
]

def page(path, title, description, body, api_name=None, endpoint=None):
    canonical = BASE + path
    schema = {'@context':'https://schema.org','@type':'WebPage','name':title,'description':description,'url':canonical}
    if api_name:
        schema['about'] = {'@type':'WebAPI','name':api_name,'url':RAPID+api_name,'documentation':canonical}
    return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+html.escape(title)+' | TNT APIs</title><meta name="description" content="'+html.escape(description,quote=True)+'"><link rel="canonical" href="'+canonical+'"><meta property="og:title" content="'+html.escape(title,quote=True)+'"><meta property="og:description" content="'+html.escape(description,quote=True)+'"><meta property="og:url" content="'+canonical+'"><meta property="og:type" content="website"><style>'+STYLE+'</style><script type="application/ld+json">'+json.dumps(schema)+'</script></head><body><main><nav><a href="/">All APIs</a><a href="/invoice-arithmetic-validator">Invoice checks</a><a href="/vn-contact-cleaner">Vietnam contacts</a><a href="/batch-duplicate-candidates">Duplicate candidates</a></nav><h1>'+html.escape(title)+'</h1><p class="note">'+html.escape(description)+'</p>'+body+'<footer><p>Hosted on Render Free. Cold starts can take 50 seconds or more; no uptime SLA. Review outputs before making changes to accounting or customer records.</p><p><a href="https://github.com/tuyentn23-dot/commerce-quality-api">Source and integration examples</a> · <a href="/health">Server health</a></p></footer></main></body></html>'

def build(destination):
    destination.mkdir(parents=True,exist_ok=True)
    cards = ''
    for slug,title,description,endpoint,request,response,details in PAGES:
        if slug == 'invoice-arithmetic-validator':
            details += '''<h2>Three checks to evaluate before integrating</h2><p>Use synthetic data first. Each request below consumes one request from your RapidAPI plan. A detected mismatch is a successful HTTP response, not an API failure.</p><table><tr><th>Check</th><th>Input</th><th>Expected result</th></tr><tr><td>Exact decimal addition</td><td>subtotal 0.10, tax 0.20, total 0.30, tolerance 0</td><td>valid true; expected_total 0.30</td></tr><tr><td>Wrong invoice total</td><td>subtotal 100, tax 10, total 120</td><td>valid false; expected total 110; difference 10</td></tr><tr><td>Wrong line amount</td><td>subtotal 20, total 20; quantity 2, unit price 8, line total 20</td><td>valid false; expected line amount 16; supplied amount 20</td></tr></table><p><a href="https://github.com/tuyentn23-dot/commerce-quality-api/blob/main/examples/validate_invoice.py">Run the three Python examples</a> using only the standard library, or paste the values into the RapidAPI playground. Inputs and expected results are also in the <a href="https://github.com/tuyentn23-dot/commerce-quality-api/blob/main/examples/trial_cases.json">synthetic evaluation kit</a>.</p><h2>Choose this check when</h2><p>You already have structured invoice amounts and need a small HTTP step that reports arithmetic mismatches before a human reviews an import. It can accompany your current extraction provider; using our extractor is optional.</p><p>If you only need one fixed calculation and can maintain code in your workflow, a local Decimal calculation may be sufficient. This service adds a consistent request contract and field-level results. It does not check purchase orders, bank accounts, supplier records or previously submitted invoices. Credit notes with negative amounts are unsupported.</p><h2>Review policy</h2><ol><li>Missing or uncertain extraction values: stop for review before validation.</li><li>Arithmetic mismatch: show the affected field, expected amount and difference to the reviewer.</li><li>Arithmetic passes: continue other checks; this is not permission to pay or post automatically.</li></ol>'''
        host=slug+'.p.rapidapi.com'
        sample="curl --request POST \\\n+  --url 'https://"+host+endpoint+"' \\\n+  --header 'Content-Type: application/json' \\\n+  --header \"X-RapidAPI-Key: $RAPIDAPI_KEY\" \\\n+  --header 'X-RapidAPI-Host: "+host+"' \\\n+  --data '"+json.dumps(request,separators=(',',':'))+"'"
        # Strip source continuation markers; they are not shell content.
        sample=sample.replace('\n+  ','\n  ')
        body='<p><a class="cta" href="'+RAPID+slug+'">Try the free BASIC plan on RapidAPI</a></p>'+details+'<h2>Request example</h2><p>Set <code>RAPIDAPI_KEY</code> to your own consumer key. Copy the host from your RapidAPI playground if your subscription shows a different host. No provider secret is needed. This example uses a POSIX shell.</p><pre><code>'+html.escape(sample)+'</code></pre><h2>Expected synthetic response</h2><pre><code>'+html.escape(json.dumps(response,indent=2))+'</code></pre><h2>Free trial and paid plan</h2><p>BASIC: $0/month, 100 requests. PRO: $4.99/month, 5,000 requests. Hard request limits; a batch counts as one request. RapidAPI displays its standard bandwidth fee separately. Check the live pricing page before subscribing.</p><h2>What if a request fails?</h2><p>401: check your RapidAPI key and subscription; do not call the provider backend directly. 413: reduce the payload below 1 MB. 422: check required fields and batch limits. Timeouts can occur during free-hosting cold starts.</p>'
        (destination/(slug+'.html')).write_text(page('/'+slug,title,description,body,slug,endpoint),encoding='utf-8')
        cards+='<section><h2><a href="/'+slug+'">'+html.escape(title)+'</a></h2><p>'+html.escape(description)+'</p><a href="'+RAPID+slug+'">View free trial and pricing</a></section>'
    body='<p>Choose the step your workflow needs: extract fields, check arithmetic, normalize contact syntax or review exact duplicate keys. These tools report structured results; review them before importing.</p>'+cards+'<section><h2>Extract invoice text to JSON</h2><p>Extract English or Vietnamese invoice fields from supplied text. OCR and document support depend on the endpoint and file quality.</p><a href="https://invoice-extract-api-4eq9.onrender.com/">Invoice Extractor guide and request example</a></section><section><h2>Vietnam address normalization</h2><p>Use the separate VN Address API for Vietnam address normalization and validation. See its current documentation for supported fields and administrative-data coverage.</p><a href="'+RAPID+'vn-address-bank-validator">VN Address on RapidAPI</a></section><h2>Common workflows</h2><ul><li>Invoice text → extracted JSON → arithmetic mismatches → manual review.</li><li>CRM contacts → +84 mobile formatting and email syntax → exact duplicate candidates → reviewed import.</li></ul><p>Start with synthetic data in the BASIC plan. No external customer count or revenue claim is made.</p>'
    (destination/'index.html').write_text(page('/','Data quality APIs for invoice and Vietnam CRM imports','Compare invoice extraction, arithmetic checks, Vietnam contact normalization and exact duplicate candidates. Practical examples and free RapidAPI trials.',body),encoding='utf-8')

if __name__=='__main__':
    build(HERE/'public')
